<?php require_once __DIR__.'/../includes/functions.php'; require_once __DIR__.'/../includes/csrf.php';$departments=db()->query('SELECT id,name FROM departments WHERE active=1 ORDER BY name')->fetchAll();$categories=db()->query('SELECT id,name FROM feedback_categories WHERE active=1 ORDER BY name')->fetchAll();?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?=e(csrf_token())?>"><title>Anonymous Feedback — <?=e(APP_NAME)?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="assets/css/style.css"></head><body><div class="survey-shell px-3"><a class="text-decoration-none fw-bold fs-4 text-dark" href="index.php">Pulse<span class="text-primary">Point</span></a><div class="panel bg-white p-4 p-md-5 mt-3"><div id="feedbackFormWrap"><div class="feature-icon mb-3"><i class="bi bi-incognito"></i></div><h1 class="fw-bold">Anonymous feedback</h1><p class="text-secondary">No sign-in is required. Choose the relevant department and share what you think the organization should know.</p><div class="alert alert-light border small"><strong>Privacy:</strong> This form does not ask for your name or email. Avoid including personally identifying information in your message unless necessary.</div><form id="feedbackForm"><div class="mb-3"><label class="form-label fw-semibold">Department</label><select name="department_id" class="form-select" required><option value="">Choose a department…</option><?php foreach($departments as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label fw-semibold">Category <span class="text-secondary fw-normal">(optional)</span></label><select name="category_id" class="form-select"><option value="">Choose a category…</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label fw-semibold">Your feedback</label><textarea name="feedback_text" class="form-control" rows="7" maxlength="5000" placeholder="Describe your concern, suggestion, experience, or idea…" required></textarea><div class="form-text">Please be specific and constructive where possible.</div></div><button class="btn btn-primary btn-lg w-100">Submit anonymously</button></form></div></div></div><script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="assets/js/app.js"></script><script>$('#feedbackForm').on('submit',function(e){e.preventDefault();const f=this,$b=$(f).find('button').prop('disabled',true).text('Submitting…');$.ajax({url:'../api/feedback.php',method:'POST',contentType:'application/json',data:JSON.stringify({action:'submit',department_id:f.department_id.value,category_id:f.category_id.value,feedback_text:f.feedback_text.value,csrf_token:PulsePoint.csrf()})}).done(()=>$('#feedbackFormWrap').html('<div class="text-center py-5"><div class="display-4 text-success">✓</div><h2 class="fw-bold mt-3">Feedback received</h2><p class="text-secondary">Thank you for speaking up. Your feedback was submitted without credentials.</p><a href="feedback.php" class="btn btn-outline-primary">Submit another</a></div>')).fail(x=>{PulsePoint.toast(x.responseJSON?.message||'Unable to submit','danger');$b.prop('disabled',false).text('Submit anonymously')})})</script></body></html>